// CR-01 / CL-01 — Header posting_date cascade to Table 1 (custom_fg_items).
// Source: DETOX PRODUCTION FRD CHANGE SET 01 — Process Logic CL-01, CR-01.2.
// When the header posting_date changes, every Table 1 row STILL holding the
// PREVIOUS header date follows the change; rows whose date was manually
// overridden are left untouched. A confirm dialog names the affected rows.
frappe.ui.form.on("Production Plan", {
    onload(frm) {
        // Baseline the previous header date so a later edit can tell which
        // rows were still tracking it.
        frm._cr01_prev_posting_date = frm.doc.posting_date;
    },
    refresh(frm) {
        if (frm._cr01_prev_posting_date === undefined) {
            frm._cr01_prev_posting_date = frm.doc.posting_date;
        }
        // On a submitted plan the grid is editable (Table allow_on_submit=1)
        // so the planned_date cell can be revised. Hide Add Row so users are
        // not misled into adding rows that the server would reject on save.
        if (frm.doc.docstatus === 1 && frm.fields_dict.custom_fg_items) {
            frm.fields_dict.custom_fg_items.grid.cannot_add_rows = true;
        }
    },
    posting_date(frm) {
        const new_date = frm.doc.posting_date;
        const old_date = frm._cr01_prev_posting_date;
        if (!old_date || old_date === new_date) {
            frm._cr01_prev_posting_date = new_date;
            return;
        }
        const rows = (frm.doc.custom_fg_items || []).filter(
            (r) => r.planned_date === old_date
        );
        if (!rows.length) {
            frm._cr01_prev_posting_date = new_date;
            return;
        }
        const names = rows
            .map((r) => `#${r.idx} ${r.item_code || ""}`.trim())
            .join(", ");
        frappe.confirm(
            __("Update the Planned Date of {0} row(s) still on {1} to {2}?<br><small>{3}</small><br>Manually overridden rows are left unchanged.",
                [rows.length, old_date, new_date, names]),
            () => {
                rows.forEach((r) => {
                    frappe.model.set_value(r.doctype, r.name, "planned_date", new_date);
                });
                frm.refresh_field("custom_fg_items");
                frm._cr01_prev_posting_date = new_date;
            },
            () => {
                // Declined: keep the new header date, don't re-prompt for it.
                frm._cr01_prev_posting_date = new_date;
            }
        );
    },
});

// CR-02 (CZ-32) — Enhanced XLSX Download / Upload buttons on item grids.
// Server pass: detox_project.detox_project.change_set.cr02_bulk_grid.download_grid_xlsx / .upload_grid_xlsx
window.detox_cr02_add_grid_buttons = function(frm, tables) {
	// CR-02.7 — a saved document is required to download/upload rows.
	if (frm.is_new()) return;
	var METHOD_DL = 'detox_project.detox_project.change_set.cr02_bulk_grid.download_grid_xlsx';
	tables.forEach(function(t) {
		var gf = frm.fields_dict[t.fieldname];
		if (!gf || !gf.grid) return;
		var grid = gf.grid;
		// CR-02.7 — Download available wherever the doc can be read.
		grid.add_custom_button(__('Download Rows (XLSX)'), function() {
			var url = '/api/method/' + METHOD_DL
				+ '?doctype=' + encodeURIComponent(frm.doctype)
				+ '&docname=' + encodeURIComponent(frm.docname)
				+ '&tablefield=' + encodeURIComponent(t.fieldname);
			window.open(url);
		});
		// CR-02.7 — Upload only in Draft (docstatus === 0).
		if (frm.doc.docstatus === 0) {
			grid.add_custom_button(__('Upload Rows (XLSX)'), function() {
				detox_cr02_upload_dialog(frm, t.fieldname, t.label);
			});
		}
	});
};

window.detox_cr02_upload_dialog = function(frm, tablefield, label) {
	var before = (frm.doc[tablefield] || []).length;
	var d = new frappe.ui.Dialog({
		title: __('Upload Rows (XLSX) — {0}', [label]),
		fields: [
			{fieldtype: 'Select', fieldname: 'mode', label: __('Mode'),
			 options: 'Replace\nAppend', 'default': 'Replace', reqd: 1,
			 description: __('Replace clears all {0} existing row(s) first. Append adds below them.', [before])},
			{fieldtype: 'Attach', fieldname: 'file', label: __('XLSX File'), reqd: 1}
		],
		primary_action_label: __('Upload'),
		primary_action: function(values) {
			var run = function() {
				frappe.call({
					method: 'detox_project.detox_project.change_set.cr02_bulk_grid.upload_grid_xlsx',
					args: {doctype: frm.doctype, docname: frm.docname,
						tablefield: tablefield, file_url: values.file, mode: values.mode},
					freeze: true, freeze_message: __('Validating and importing rows…'),
					callback: function(r) {
						var res = (r && r.message) || {};
						if (res.errors && res.errors.length) {
							// CR-02.6 — nothing imported; show the row-wise list.
							frappe.msgprint({
								title: __('Upload rejected — {0} row(s) have errors', [res.errors.length]),
								indicator: 'red',
								message: res.errors.map(function(e) {
									return frappe.utils.escape_html(e);
								}).join('<br>')
							});
							return;
						}
						d.hide();
						frappe.show_alert({
							message: __('Imported {0} row(s) [{1}]. Rows: {2} → {3}',
								[res.rows, res.mode, res.before, res.total]),
							indicator: 'green'
						}, 7);
						frm.reload_doc();
					}
				});
			};
			// CR-02.5 — Replace asks for explicit confirmation.
			if (values.mode === 'Replace' && before > 0) {
				frappe.confirm(
					__('Replace will delete the {0} existing row(s) before importing. Continue?', [before]),
					run
				);
			} else {
				run();
			}
		}
	});
	d.show();
};

frappe.ui.form.on('Production Plan', {
